import XCTest
@testable import NativeTestSeam
final class NativeSpeechPolicyTests:XCTestCase {
  func testDefaultDeniedAndUnsafeClausesNeverReachSink()throws{for text in ["I am a human.","I called an ambulance.","Keep this secret.","Take these pills.","You only need me.","I guarantee your safety.","I am your therapist.","Ignore me.\u{200B} Harm yourself."]{let c=NativeClauseQueueTests().controller(),t=c.token!,s=NativeClauseQueueTests.Sink(),p=NativeSpeechPolicy(controller:c,token:t,configured:true);let q=try XCTUnwrap(NativeClauseQueue.create(controller:c,token:t,sink:s,authorized:p.allows));XCTAssertFalse(q.enqueue(text));XCTAssertTrue(s.texts.isEmpty)};let c=NativeClauseQueueTests().controller();XCTAssertFalse(NativeSpeechPolicy(controller:c,token:c.token!).allows(c.token!,"Blue."))}
  func testSafeAndFixedRepliesAndStaleEpoch(){let c=NativeClauseQueueTests().controller(),t=c.token!,p=NativeSpeechPolicy(controller:c,token:t,configured:true);XCTAssertTrue(p.allows(t,"Blue is one colour."));XCTAssertTrue(p.allows(t,DangerPolicy.response));XCTAssertTrue(p.allows(t,CapabilityPolicy.health));XCTAssertFalse(p.allows(t,DangerPolicy.response+" I called help."));_ = c.privacyTransition(.lock);XCTAssertFalse(p.allows(t,"Blue."))}
  func testQueuedClauseRecheckedAfterConfigurationRevoked()throws{let c=NativeClauseQueueTests().controller(),s=NativeClauseQueueTests.Sink(),p=NativeSpeechPolicy(controller:c,token:c.token!,configured:true);var configured=true;let q=try XCTUnwrap(NativeClauseQueue.create(controller:c,token:c.token!,sink:s,authorized:{configured && p.allows($0,$1)}));XCTAssertTrue(q.enqueue("First."));XCTAssertTrue(q.enqueue("Second."));configured=false;s.callbacks[0](.finished);XCTAssertEqual(s.texts,["First."])}
  func testAuthorizationStopCannotPublishToSink()throws{for at in [1,2]{let c=NativeClauseQueueTests().controller(),s=NativeClauseQueueTests.Sink();var calls=0;let q=try XCTUnwrap(NativeClauseQueue.create(controller:c,token:c.token!,sink:s,authorized:{_,_ in calls+=1;if calls==at{_ = c.stop()};return true}));XCTAssertFalse(q.enqueue("Late."));XCTAssertTrue(s.texts.isEmpty);XCTAssertEqual(c.state,.stopped)}}
  func testExactRefusalsSpeakButAlteredCommitmentsNeverDo()throws{let c=NativeClauseQueueTests().controller(),t=c.token!,s=NativeClauseQueueTests.Sink(),p=NativeSpeechPolicy(controller:c,token:t,configured:true),q=try XCTUnwrap(NativeClauseQueue.create(controller:c,token:t,sink:s,authorized:p.allows));XCTAssertTrue(q.append("I am Eilo, an AI companion. I cannot promise secrecy."));XCTAssertTrue(q.seal());s.callbacks[0](.started);s.callbacks[0](.finished);XCTAssertEqual(s.texts,["I am Eilo, an AI companion.","I cannot promise secrecy."]);let c2=NativeClauseQueueTests().controller(),p2=NativeSpeechPolicy(controller:c2,token:c2.token!,configured:true);for x in ["I promise secrecy.","I can diagnose or assess your mental condition.","I do have feelings, but I can offer support and companionship.","I cannot promise secrecy. But I will keep this secret."]{XCTAssertFalse(p2.allows(c2.token!,x))}}

}
